 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0 and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            components.append(comp)
    panel = max(components, key=lambda comp: sum(grid[r][c] == 1 for r, c in comp))
    r0, r1 = min(r for r, c in panel), max(r for r, c in panel)
    c0, c1 = min(c for r, c in panel), max(c for r, c in panel)
    src = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
    H, W = len(src), len(src[0])
    panel_set = set(panel)
    outer = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] != 0 and (r, c) not in panel_set]

    # The three isolated same-color markers outside the panel form an L.
    # Their spatial directions determine the dihedral transformation of the panel.
    by_color = {v: (r, c) for r, c, v in outer}
    colors = set(by_color)
    # Determine whether the target layout's long arm is horizontal or vertical,
    # then compare which colors sit at its two ends and at the elbow.
    # Matching color arrangement inside the panel identifies exact orientation.
    marker = {v: [(r, c) for r in range(H) for c in range(W) if src[r][c] == v]
              for v in colors}
    marker = {v: ps[0] for v, ps in marker.items() if ps}

    transforms = [
        (H, W, lambda r, c: (r, c)),
        (H, W, lambda r, c: (r, W-1-c)),
        (H, W, lambda r, c: (H-1-r, c)),
        (H, W, lambda r, c: (H-1-r, W-1-c)),
        (W, H, lambda r, c: (c, r)),
        (W, H, lambda r, c: (W-1-c, H-1-r)),
        (W, H, lambda r, c: (c, H-1-r)),
        (W, H, lambda r, c: (W-1-c, r)),
    ]
    # Compare relative marker geometry after each transform against external marker layout.
    er = [p[0] for p in by_color.values()]
    ec = [p[1] for p in by_color.values()]
    ext_norm = {v: (r-min(er), c-min(ec)) for v, (r,c) in by_color.items()}
    best = None
    best_score = -1
    for OH, OW, fn in transforms:
        if not colors.issubset(marker):
            continue
        points = {v: fn(*marker[v]) for v in colors}
        pr = [p[0] for p in points.values()]
        pc = [p[1] for p in points.values()]
        norm = {v: (r-min(pr), c-min(pc)) for v,(r,c) in points.items()}
        # External markers are a translated/scaled (usually spaced) L; compare ordering
        # on both axes, not pixel distances.
        score = 0
        for a in colors:
            for b in colors:
                if (ext_norm[a][0] < ext_norm[b][0]) == (norm[a][0] < norm[b][0]) and ext_norm[a][0] != ext_norm[b][0] and norm[a][0] != norm[b][0]:
                    score += 1
                if (ext_norm[a][1] < ext_norm[b][1]) == (norm[a][1] < norm[b][1]) and ext_norm[a][1] != ext_norm[b][1] and norm[a][1] != norm[b][1]:
                    score += 1
        if score > best_score:
            best_score, best = score, (OH, OW, fn)
    OH, OW, fn = best
    out = [[0] * OW for _ in range(OH)]
    for r in range(H):
        for c in range(W):
            rr, cc = fn(r, c)
            out[rr][cc] = src[r][c]
    return out
